@route("/safeid/<token>/qr-card")
def safeid_qr_card(token):
    """Large, scan-first QR view opened from the installed home-screen QR icon."""
    token = _safeid_install_token(token)
    ar = _lang() == "ar"
    share_url = _safeid_share_url(token)
    qr = privacy_features.qr_png_data_uri(share_url)
    if not qr:
        abort(503)
    body = r"""
    <main class="sid-homeqr">
      <section class="sid-homeqr-card">
        <span class="sid-homeqr-badge">🚑 SymptoSense</span>
        <h1>__TITLE__</h1>
        <p>__SUB__</p>
        <div class="sid-homeqr-code"><img src="__QR__" alt="Emergency QR"></div>
        <strong>__SCAN__</strong>
        <a class="sid-homeqr-open" href="__URL__">__OPEN__</a>
      </section>
    </main>
    """
    body = (body
        .replace("__TITLE__", "معك وقت الحاجة" if ar else "Here when needed")
        .replace("__SUB__", "اعرض هذا الرمز لمن يساعدك وقت الطوارئ." if ar else "Show this code to someone helping you in an emergency.")
        .replace("__QR__", html_lib.escape(qr, quote=True))
        .replace("__SCAN__", "امسح الرمز لعرض معلومات الطوارئ وجهة الاتصال" if ar else "Scan to view emergency information and contact")
        .replace("__URL__", html_lib.escape(share_url, quote=True))
        .replace("__OPEN__", "فتح معلومات الطوارئ" if ar else "Open emergency information"))
    css = r"""
    .sid-homeqr{min-height:75vh;display:grid;place-items:center;padding:20px}.sid-homeqr-card{width:min(440px,100%);text-align:center;background:#fff;border:1px solid #d9e8f1;border-radius:26px;padding:26px;box-shadow:0 18px 55px rgba(32,94,130,.10)}.sid-homeqr-badge{display:inline-flex;padding:7px 11px;border-radius:999px;background:#eaf5fb;color:#176f9e;font-weight:900;font-size:12px}.sid-homeqr-card h1{color:#123B70;margin:14px 0 5px}.sid-homeqr-card p{color:#6f8393;margin:0 0 18px}.sid-homeqr-code{width:min(320px,82vw);aspect-ratio:1;margin:0 auto 13px;padding:12px;border:1px solid #d8e5ed;border-radius:20px;background:#fff;display:grid;place-items:center}.sid-homeqr-code img{width:100%;height:100%;object-fit:contain}.sid-homeqr-card strong{display:block;color:#36586d;font-size:12px;line-height:1.7}.sid-homeqr-open{display:block;margin-top:16px;text-decoration:none;border-radius:13px;background:#147ab5;color:#fff;padding:12px;font-weight:900}
    """
    page = _page(
        "معك وقت الحاجة | SymptoSense" if ar else "Here when needed | SymptoSense",
        body,
        desc=("رمز الطوارئ الخاص بك." if ar else "Your emergency QR code."),
        extra_css=css,
    )
    qtoken = quote(token, safe="")
    page = page.replace(
        '<link rel="manifest" href="/manifest.webmanifest">',
        '<link rel="manifest" href="/safeid/%s/manifest.webmanifest">' % qtoken, 1
    ).replace(
        '<link rel="apple-touch-icon" sizes="180x180" href="/icons/apple-touch-icon.png">',
        '<link rel="apple-touch-icon" sizes="180x180" href="/safeid/%s/qr-icon-180.png">' % qtoken, 1
    ).replace(
        '<meta name="apple-mobile-web-app-title" content="SymptoSense">',
        '<meta name="apple-mobile-web-app-title" content="معك وقت الحاجة">', 1
    )
    response = make_response(page)
    response.headers["X-Robots-Tag"] = "noindex, nofollow, noarchive"
    response.headers["Cache-Control"] = "no-store, private"
    return response


