@route('/health-library/<kind>/<slug>')
def health_library_detail(kind, slug):
    if kind not in ("disease", "symptom"):
        abort(404)
    lang = _lang()
    result = health_library.detail(kind, slug, lang)
    if result is None:
        abort(404)
    title, desc, body = result
    return _page(title, body, desc=desc)


