    css = '''.method-page{width:min(1080px,100%);margin:auto;display:grid;gap:20px}.method-hero,.method-note,.method-grid>article{padding:30px;border:1px solid #DCE8F0;border-radius:24px;background:#F8FCFF}.method-tag{display:inline-flex;padding:7px 11px;border-radius:999px;background:#EAF5FC;color:#1f6fae;font-weight:900;font-size:12px}.method-hero h1{color:#123B70;font-size:clamp(28px,4vw,44px);margin:12px 0}.method-hero p,.method-note p,.method-grid p,.method-grid li{color:#60788B;line-height:1.85}.method-flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.method-flow article{padding:22px;border:1px solid #DCE8F0;border-radius:20px;background:#fff}.method-flow b{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;background:#1f6fae;color:#fff}.method-flow h3,.method-note h2,.method-grid h2{color:#123B70}.method-flow p{color:#60788B;line-height:1.7}.method-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.method-grid ul{padding-inline-start:22px;margin-bottom:0}@media(max-width:800px){.method-flow{grid-template-columns:1fr 1fr}.method-grid{grid-template-columns:1fr}}@media(max-width:520px){.method-flow{grid-template-columns:1fr}.method-hero,.method-note,.method-grid>article{padding:22px 18px}}'''
    return _page(bi("منهجية SymptoSense", "SymptoSense Methodology"), body, extra_css=css)


