@route("/api/consent/preferences", methods=["POST"])
def api_consent_preferences():
    try:
        data = request.get_json(silent=True) or {}
        # Service/analytics are explicit booleans. Research is a separate optional
        # choice; omitted research values preserve the prior decision so older
        # clients cannot silently enroll or withdraw a participant.
        service = data.get("service_usage") is True
        analytics = data.get("analytics_research") is True
        research = (data.get("research_participation") is True) if "research_participation" in data else None
        state = privacy_features.save_consent(_consent_subject_key(), _ss_user_id(), service, analytics, research)
        if not _ss_user_id():
            # Keep the guest fast-path authoritative for this browser immediately
            # after saving, without an extra PostgreSQL read on the redirect.
            session["_guest_consent_state"] = {
                k: state.get(k) for k in (
                    "service_usage", "analytics_research", "research_participation",
                    "ai_improvement", "consent_version", "privacy_policy_version",
                    "needs_review", "updated_at"
                )
            }
            session.pop("_guest_consent_db_empty", None)
        return jsonify({"ok": True, "consent": state})
    except Exception as e:
        return _mk_error(e, 500)


