@route("/sitemap.xml")
def sitemap_xml():
    base = _site_url().rstrip("/")
    # Canonical public pages only. Legacy unprefixed pages are 301 redirects and
    # never appear here, preventing duplicate language/indexation signals.
    pages = [
        "/", "/search", "/calculators", "/meds",
        "/emergency", "/firstaid", "/tips", "/relax", "/about",
        "/how-we-work", "/community-dashboard", "/health-trends",
        "/health-library", "/privacy", "/terms",
    ]
    core_priority = {"/": 1.0, "/chat": 0.9, "/blood": 0.9, "/how-we-work": 0.8, "/about": 0.8}
    rows = []
    for suffix in pages:
        ar_path = "/ar/" if suffix == "/" else "/ar" + suffix
        en_path = "/en/" if suffix == "/" else "/en" + suffix
        priority = core_priority.get(suffix, 0.7)
        for lang, loc_path in (("ar", ar_path), ("en", en_path)):
            loc = html_lib.escape(base + loc_path, quote=True)
            ar_href = html_lib.escape(base + ar_path, quote=True)
            en_href = html_lib.escape(base + en_path, quote=True)
            rows.append(
                '  <url><loc>%s</loc>'
                '<xhtml:link rel="alternate" hreflang="ar" href="%s"/>'
                '<xhtml:link rel="alternate" hreflang="en" href="%s"/>'
                '<xhtml:link rel="alternate" hreflang="x-default" href="%s"/>'
                '<priority>%.1f</priority></url>'
                % (loc, ar_href, en_href, (html_lib.escape(base, quote=True) + "/") if suffix == "/" else ar_href, priority)
            )
    xml = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n%s\n</urlset>\n'
        % "\n".join(rows)
    )
    response = Response(xml, mimetype="application/xml")
    response.headers["Cache-Control"] = "public, max-age=3600"
    return response


@route("/api/stats")
def api_stats():
    db.init_db()
    privacy_features.init_schema()  # creates records.analytics_eligible (optional schemas are lazy at startup)
    stats = db.get_usage_stats(days=7)
    trends, _ = db.get_trends(days=7)
    top_symptoms = trends.most_common(8)
    urgency = dict(db.fetchall("SELECT urgency, COUNT(*) FROM records WHERE COALESCE(analytics_eligible,0)=1 GROUP BY urgency"))
    lang = dict(db.fetchall("SELECT lang, COUNT(*) FROM records WHERE COALESCE(analytics_eligible,0)=1 GROUP BY lang"))
    ages = [row[0] for row in db.fetchall("SELECT age FROM records WHERE age IS NOT NULL AND COALESCE(analytics_eligible,0)=1")]
    age_groups = {"0-17": 0, "18-30": 0, "31-45": 0, "46-60": 0, "60+": 0}
    for a in ages:
        if a <= 17: age_groups["0-17"] += 1
        elif a <= 30: age_groups["18-30"] += 1
        elif a <= 45: age_groups["31-45"] += 1
        elif a <= 60: age_groups["46-60"] += 1
        else: age_groups["60+"] += 1
    feedback = db.feedback_counts()
    return jsonify({
        "stats": stats,
        "symptoms": top_symptoms,
        "urgency": urgency,
        "lang": lang,
        "age_groups": list(age_groups.items()),
        "feedback": feedback,
        "feedback_reasons": db.feedback_reason_stats(),
        # Admin reviews anonymous comment text only; user identities are not returned.
        "fb_comments": db.feedback_comments(100, public_only=False),
        "assistant_feedback": db.assistant_feedback_stats(),
        "db_backend": "PostgreSQL" if db.USE_POSTGRES else "SQLite",
    })


