@route("/share/health/<token>")
def public_health_handoff(token):
    item=privacy_features.get_handoff(token); ar=_lang()=="ar"
    if not item or item.get("status") in ("expired","revoked"):
        msg=("هذا الرابط لم يعد متاحًا." if item and item.get("status")=="revoked" else "انتهت صلاحية رابط الملخص الصحي أو أنه غير صالح.") if ar else ("This link is no longer available." if item and item.get("status")=="revoked" else "This health summary link has expired or is invalid.")
        return _page("Health Summary",'<main class="v2-info-page"><section style="text-align:center"><h1>🔒 Health Summary</h1><p>%s</p></section></main>'%msg),410
    payload=item.get("payload") or {}; sec=payload.get("sections") or {}; lang="en" if payload.get("lang")=="en" else "ar"; ar=lang=="ar"
    labels={"symptoms":"الأعراض المبلغ عنها" if ar else "Reported Symptoms","duration":"المدة" if ar else "Duration","severity":"الشدة" if ar else "Severity","location":"المكان" if ar else "Location","notes":"معلومات إضافية" if ar else "Additional Information","medications":"معلومات الأدوية التي اختار المستخدم مشاركتها" if ar else "Medication information selected by the user","previous_assessments":"تقييمات سابقة مختارة" if ar else "Selected Previous Assessments"}
    blocks=[]
    for key in ("symptoms","duration","severity","location","notes","medications"):
        val=sec.get(key)
        if val not in (None,"",[]):
            if isinstance(val,list): val="، ".join(map(str,val)) if ar else ", ".join(map(str,val))
            blocks.append('<section><h2>%s</h2><p>%s</p></section>'%(html_lib.escape(labels[key]), html_lib.escape(str(val), quote=True)))
    prev=sec.get("previous_assessments") or []
    if prev:
        lis=''.join(
            '<li>%s — %s — %s</li>' % (
                html_lib.escape(("، ".join(map(str, x.get("symptoms") or [])) if ar else ", ".join(map(str, x.get("symptoms") or []))), quote=True),
                html_lib.escape(str(x.get("duration") or "—"), quote=True),
                html_lib.escape(str(x.get("risk_level") or "—"), quote=True),
            )
            for x in prev if isinstance(x, dict)
        )
        blocks.append('<section><h2>%s</h2><ul>%s</ul></section>'%(html_lib.escape(labels["previous_assessments"]),lis))
    if not blocks:
        empty_msg = "لا توجد معلومات متاحة ضمن الحقول التي اختارها المستخدم لهذا الرابط. أنشئ رابط مشاركة جديدًا واختر معلومات موجودة في التحليل." if ar else "No information is available in the fields selected for this link. Create a new share link and choose information that exists in the analysis."
        blocks.append('<section><p class="v2-safe-note">%s</p></section>' % empty_msg)
    disc="يحتوي هذا الملخص على معلومات أبلغ عنها المستخدم ويهدف للمساعدة في توصيل المعلومات إلى مختص صحي. لا يحل محل التقييم الطبي المتخصص." if ar else "This summary contains user-reported information and is intended to help communicate information to a healthcare professional. It does not replace professional medical evaluation."
    body='<main class="v2-info-page"><section><h1>🗣️ SymptoSense Health Summary</h1><p class="muted">%s</p></section>%s<section><p class="v2-disclaimer">%s</p></section></main>'%(html_lib.escape(str(payload.get("created_at") or ""), quote=True),''.join(blocks),html_lib.escape(disc, quote=True))
    return _page("SymptoSense Health Summary",body)


@route("/api/hospitals", methods=["POST"])
def api_hospitals():
    # This endpoint calls an external geospatial provider and receives precise
    # coordinates supplied by the browser, so keep abuse bounded independently.
    if not _request_allowed(
        "nearby_hospitals",
        _bounded_env_int("HOSPITALS_RATE_LIMIT_MAX", 12, 2, 120),
        _bounded_env_int("HOSPITALS_RATE_LIMIT_WINDOW_SECONDS", 300, 60, 3600),
    ):
        return _rate_limited_response()
    data = request.get_json(silent=True) or {}
    try:
        lat, lng = float(data.get("lat")), float(data.get("lng"))
        if not (-90 <= lat <= 90 and -180 <= lng <= 180):
            raise ValueError("invalid_coordinates")
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "إحداثيات غير صالحة." if _lang()=="ar" else "Invalid coordinates.", "error_code": "invalid_coordinates"}), 400
    try:
        hospitals = geo_hospitals.find_nearby_hospitals(lat, lng) or []
        if hospitals:
            return jsonify({"ok": True, "hospitals": hospitals, "fallback": False})
        # Overpass can be rate-limited or temporarily unavailable.  Keep the
        # location feature useful by returning a map search centered on the
        # coordinates the user explicitly shared for this request.
        maps_url = f"https://www.google.com/maps/search/hospitals/@{lat:.6f},{lng:.6f},14z"
        name = "فتح المستشفيات القريبة على الخريطة" if _lang()=="ar" else "Open nearby hospitals on the map"
        return jsonify({"ok": True, "hospitals": [{"name": name, "distance_km": None, "maps_url": maps_url, "map_fallback": True}], "fallback": True})
    except Exception:
        logging.getLogger(__name__).warning("Handled exception in api_hospitals; fallback applied (handler 18094)")
        maps_url = f"https://www.google.com/maps/search/hospitals/@{lat:.6f},{lng:.6f},14z"
        name = "فتح المستشفيات القريبة على الخريطة" if _lang()=="ar" else "Open nearby hospitals on the map"
        return jsonify({"ok": True, "hospitals": [{"name": name, "distance_km": None, "maps_url": maps_url, "map_fallback": True}], "fallback": True})


def register_routes(app, namespace):
    """Inject webapp dependencies, apply the original decorators, and add the URL rules (same endpoint names)."""
    missing = [n for n in DEPS if n not in namespace]
    if missing:
        raise RuntimeError("routes.pages: missing dependencies %s" % missing)
    g = globals()
    for n in DEPS:
        g[n] = _inject.dependency(namespace, n)
    g["app"] = app
    for name, spec in _SPECS.items():
        view = spec["fn"]
        for w in reversed(_WRAPPERS.get(name, ())):
            view = _inject.resolve_wrapper(w, g)(view)
        for rule, opts in spec["rules"]:
            kw = dict(opts)
            endpoint = kw.pop("endpoint", name)
            app.add_url_rule(rule, endpoint=endpoint, view_func=view, **kw)
